            <h2 id="entryEditTitle">新建条目</h2>
            <div class="edit-actions">
              <button id="cancelEntryBtn" class="secondary">返回</button>
              <button id="saveEntryBtn" class="success">保存</button>
            </div>
          </div>

          <form id="entryForm">
            <input type="hidden" id="entryUid" />
            <div class="form-group">
              <label for="entryComment">标题/备注：</label>
              <input type="text" id="entryComment" required />
            </div>

