              <div class="toggle-container">
                <label for="entryEnabled">启用：</label>
                <label class="toggle-switch">
                  <input type="checkbox" id="entryEnabled" checked />
                  <span class="slider"></span>
                </label>
              </div>
            </div>

            <div class="form-group">
              <label for="entryType">类型：</label>
              <select id="entryType">
                <option value="constant">常量（蓝灯）</option>
                <option value="selective">选择性（绿灯）</option>
                <option value="vectorized">向量化（紫灯）</option>
              </select>
            </div>

            <div class="form-group">
              <label for="entryPosition">位置：</label>
              <select id="entryPosition">
                <option value="before_character_definition">角色定义之前</option>
                <option value="after_character_definition">角色定义之后</option>
                <option value="before_example_messages">示例消息之前</option>
                <option value="after_example_messages">示例消息之后</option>
                <option value="before_author_note">作者注释之前</option>
                <option value="after_author_note">作者注释之后</option>
                <option value="at_depth_as_system">@D⚙</option>
                <option value="at_depth_as_assistant">@D👤</option>
                <option value="at_depth_as_user">@D🤖</option>
              </select>
            </div>

            <div class="form-group" id="depthGroup" style="display: none">
              <label for="entryDepth">深度：</label>
              <input type="number" id="entryDepth" min="0" value="0" />
            </div>

            <div class="form-group">
              <label for="entryOrder">顺序：</label>
              <input type="number" id="entryOrder" min="0" value="100" />
            </div>

            <div class="form-group">
              <label for="entryProbability">概率（%）：</label>
              <input type="number" id="entryProbability" min="0" max="100" value="100" />
            </div>

            <div class="form-group">
              <label for="entryKeys">关键词（逗号分隔）：</label>
              <input type="text" id="entryKeys" placeholder="关键词1,关键词2,..." />
            </div>

            <div class="form-group">
              <label for="entryLogic">匹配逻辑：</label>
              <select id="entryLogic">
                <option value="and_any">任意一个关键词（OR）</option>
                <option value="and_all">所有关键词（AND）</option>
                <option value="not_all">排除所有关键词</option>
                <option value="not_any">排除任意关键词</option>
              </select>
            </div>

            <div class="form-group">
              <label for="entryContent">内容：</label>
              <textarea id="entryContent" required></textarea>
            </div>
          </form>
        </div>

        <!-- 导入世界书条目视图 -->
        <div id="importView" class="view">
          <div class="edit-header">
            <h2>导入世界书条目</h2>
